-- 시연용 초기 데이터 (npm run demo:sql 로 만듦 — 직접 고치지 말고 scripts/demo/make-seed.mjs 를 고친다). 사용법: docs/시연데이터.md
-- test1~test4 계정이 먼저 가입돼 있어야 한다.
-- 네 계정의 기존 내용(기록·과목·할 일·일정·목표·경험치·스터디)을 지우고 새로 넣는다. 계정 자체는 그대로 둔다.

-- 0) 안전장치: test1~test4 네 계정이 모두 있어야 진행한다. 하나라도 없으면 이 줄에서 오류(malformed JSON)로 멈추고 아무것도 바꾸지 않는다.
SELECT CASE WHEN (SELECT COUNT(*) FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4')) = 4 THEN 'ok' ELSE json('test1~test4 계정이 모두 있어야 합니다') END AS check_accounts;

-- 1) 네 계정의 기존 내용 지우기
DELETE FROM record_comments WHERE user_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4')) OR session_id IN (SELECT id FROM study_sessions WHERE user_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4'))) OR study_id IN (SELECT id FROM studies WHERE owner_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4')) OR invite_code = 'SCNUSTDY');
DELETE FROM record_cheers WHERE user_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4')) OR session_id IN (SELECT id FROM study_sessions WHERE user_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4'))) OR study_id IN (SELECT id FROM studies WHERE owner_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4')) OR invite_code = 'SCNUSTDY');
DELETE FROM study_members WHERE user_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4')) OR study_id IN (SELECT id FROM studies WHERE owner_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4')) OR invite_code = 'SCNUSTDY');
DELETE FROM studies WHERE id IN (SELECT id FROM studies WHERE owner_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4')) OR invite_code = 'SCNUSTDY');
DELETE FROM xp_events WHERE user_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4'));
DELETE FROM study_sessions WHERE user_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4'));
DELETE FROM subjects WHERE user_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4'));
DELETE FROM todos WHERE user_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4'));
DELETE FROM events WHERE user_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4'));
DELETE FROM weekly_goal_items WHERE user_id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4'));
UPDATE users SET display_stage = NULL WHERE id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4'));

