-- 6) 확인: 계정별 경험치 합계 (test1 998, test2 4760, test3 1790, test4 190 이 나와야 한다)
SELECT u.login_id, (SELECT COALESCE(SUM(amount), 0) FROM xp_events WHERE user_id = u.id) AS xp, (SELECT COUNT(*) FROM study_sessions WHERE user_id = u.id) AS records FROM users u WHERE u.id IN (SELECT id FROM users WHERE login_id IN ('test1', 'test2', 'test3', 'test4')) ORDER BY u.login_id;
